import{z as o,x as s,o as r,c as n,q as t,j as i,D as E,d as A,s as l,S as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"关键面积","description":"","frontmatter":{"title":"关键面积","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/critical-area.md","filePath":"litho/critical-area.md","lastUpdated":1791063341000}'),p={name:"litho/critical-area.md"};function c(m,a,d,h,_,D){const e=s("Mermaid");return r(),n("div",null,[a[2]||(a[2]=t('<h1 id="关键面积" tabindex="-1">关键面积 <a class="header-anchor" href="#关键面积" aria-label="Permalink to &quot;关键面积&quot;">​</a></h1><div class="epigraph"><p>同样大小的颗粒，落在密线缝里会桥，落在空白里无事；关键面积把版图与缺陷尺寸合成「能杀死管芯的那部分面积」。</p><footer>—— 对照 Maly 等对 critical area 的论述；IC 良率对布局灵敏度的通称</footer></div><p><a href="/litho/yield-models">上一课</a>用 \\(DA\\) 做账。缺口是 \\(A\\) 不是芯片外形面积：只有能造成短路、开路、via 失效的几何才算。<a href="/litho/design-rule-origin">设计规则起源</a> 已说规则是失效代理；本课钉关键面积（critical area）计算。系统热点对随机颗粒，留给<a href="/litho/systematic-vs-random-defects">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>关键面积 \\(A_\\mathrm{cr}(r)\\) 对缺陷半径 \\(r\\) 积分，再与尺寸分布相乘得失败率。密金属、小 tip、via 覆盖不足让 \\(A_\\mathrm{cr}\\) 膨胀——同一洁净度下良率更差。冗余 via、加宽、放宽 tip 是用面积换良率，与 LFD 的可印性谈判叠在一起。</p><p>缺口是<strong>布局灵敏度</strong>，不是再拟合负二项。DTCO 加轨或加 dummy 会改 \\(A_\\mathrm{cr}\\)，也改刻蚀负载，账要联立。</p><h3 id="光刻系统失效不是颗粒关键面积" tabindex="-1">光刻系统失效不是颗粒关键面积 <a class="header-anchor" href="#光刻系统失效不是颗粒关键面积" aria-label="Permalink to &quot;光刻系统失效不是颗粒关键面积&quot;">​</a></h3><p>OPC 热点在每颗管芯同一地点桥连，关键面积公式假定缺陷位置随机。系统失效应单列，否则 \\(D\\) 会被估爆，洁净室会去抓不存在的颗粒。</p><p><span class="marginnote">缺陷尺寸分布通常来自检测，有漏检。\\(A_\\mathrm{cr}\\) 对小 \\(r\\) 敏感，而小缺陷恰是光学检测最弱处——电子束课会补。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>提取：对每层做短路/开路关键面积（多边形膨胀–重叠一类算法）。输入：缺陷尺寸分布。输出：按层的失败率贡献，指导哪层该加冗余 via 或放宽。与 SRAM：阵列 \\(A_\\mathrm{cr}\\) 极高且周期，单独算。与 via 协同：enclosure 进入开路关键面积。</p><p>尺寸分布要用复检校准后的检测数据，并声明漏检。Maly 的 critical area 是布局灵敏度；输入错了，冗余 via 会加在错误的层上。</p><p>关键面积这个数字在产线上是怎么算出来的？是一条「版图进、失败率出」的流水线：先把版图按失效模式逐层扫描，再把几何灵敏度与检测到的缺陷尺寸分布对账，最后决定冗余花在哪层。</p>',13)),(r(),i(B,null,{default:E(()=>[l(e,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%AF%8F%E5%B1%82%E7%89%88%E5%9B%BE%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20DIL%5B%22%E6%8C%89%E7%BC%BA%E9%99%B7%E5%B0%BA%E5%AF%B8%E5%81%9A%E8%86%A8%E8%83%80%E4%B8%8E%E9%87%8D%E5%8F%A0%E6%89%AB%E6%8F%8F%22%5D%0A%20%20DIL%20--%3E%20CA%5B%22%E7%9F%AD%E8%B7%AF%20%2F%20%E5%BC%80%E8%B7%AF%E5%85%B3%E9%94%AE%E9%9D%A2%E7%A7%AF%E6%9B%B2%E7%BA%BF%20A_cr(r)%22%5D%0A%20%20DD%5B%22%E5%A4%8D%E6%A3%80%E6%A0%A1%E5%87%86%E5%90%8E%E7%9A%84%E7%BC%BA%E9%99%B7%E5%B0%BA%E5%AF%B8%E5%88%86%E5%B8%83%22%5D%20--%3E%20MUL%5B%22%E6%8C%89%E5%B0%BA%E5%AF%B8%E5%8A%A0%E6%9D%83%E7%A7%AF%E5%88%86%22%5D%0A%20%20CA%20--%3E%20MUL%0A%20%20MUL%20--%3E%20FR%5B%22%E6%8C%89%E5%B1%82%E5%A4%B1%E8%B4%A5%E7%8E%87%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20FR%20--%3E%20DEC%7B%22%E5%93%AA%E5%B1%82%E6%9C%80%E7%96%BC%EF%BC%9F%22%7D%0A%20%20DEC%20--%3E%7C%22via%20%E8%A6%86%E7%9B%96%E7%B4%A7%22%7C%20R1%5B%22%E5%8A%A0%E5%86%97%E4%BD%99%20via%22%5D%0A%20%20DEC%20--%3E%7C%22tip%20%E9%97%B4%E8%B7%9D%E7%B4%A7%22%7C%20R2%5B%22%E6%94%BE%E5%AE%BD%20tip%20%E6%88%96%E5%8A%A0%E5%AE%BD%E9%97%B4%E9%9A%94%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：关键面积就是「靶子有多大」。随机颗粒是乱飞的子弹，密线之间的窄缝是靶环——缝越窄、线越长、via 越密，靶环总面积越大，中靶概率越高。在空白大片区域飞过一百发子弹可能一发不中，同样的子弹撒在 SRAM 阵列上就是弹弹见血。</span></p><p><span class="marginnote">数字实例：半径 \\(r\\) 的圆形颗粒要桥连两条线，需两线间距小于 \\(2r\\)。若某层最小金属间距 \\(40\\) nm，则直径大于 \\(40\\) nm 的颗粒才有资格致短路；而电源线之间留了 \\(200\\) nm 空隙，就要直径 \\(200\\) nm 的大颗粒才致命。同一批颗粒落下来，密层天然比疏层危险——这就是 \\(A_\\mathrm{cr}(r)\\) 随 \\(r\\) 增长的几何含义。</span></p><p><span class="marginnote">常见误区：初学者容易把良率模型里的 \\(A\\) 当成芯片外形面积。实际上只有「颗粒落下去会致命」的那部分几何才计入关键面积——两块外形一样大的芯片，一层密布线与一层稀疏布线的关键面积可以差好几倍，良率也因此不同。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>半径 \\(r\\) 的圆（或方）缺陷，若其落点使两导体间距 \\(\\lt\\) 2r 则短路。积分对间距分布敏感，故最小间隔规则直接杠杆 \\(A_\\mathrm{cr}\\)。多重图形的异色间距还含套刻，有效间隔随机化，关键面积要用套刻分布卷积——EPE 预算在良率上的样子。</p>',5)),(r(),i(B,null,{default:E(()=>[l(e,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAY%5B%22%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20CA%5B%22A_cr(r)%22%5D%0A%20%20DIST%5B%22%E7%BC%BA%E9%99%B7%E5%B0%BA%E5%AF%B8%E5%88%86%E5%B8%83%22%5D%20--%3E%20Y%5B%22%E9%9A%8F%E6%9C%BA%E9%A2%97%E7%B2%92%E5%A4%B1%E8%B4%A5%E7%8E%87%22%5D%0A%20%20CA%20--%3E%20Y%0A%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E7%83%AD%E7%82%B9%22%5D%20--%3E%20SEP%5B%22%E5%8D%95%E7%8B%AC%E5%88%97%E8%B4%A6%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>系统热点单列，不并进 A_cr D。缺陷尺寸分布必须经复检校准，否则冗余 via 会加错层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>计算不替代硅上检测。不把某 EDA 关键面积模块当物理定律。颗粒形状不是圆，模型是工程近似。</p><p>后课默认：随机颗粒良率用关键面积加权。下一课强制把系统图形化失效从 \\(D\\) 里拆走。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>关键面积是布局对随机缺陷的灵敏度，不是芯片外形。</li><li>系统热点不可并进 \\(A_\\mathrm{cr}D\\)。</li><li>冗余 via 与 tip 规则直接杠杆 \\(A_\\mathrm{cr}\\)。</li><li>套刻使异色间距随机化，关键面积要对 EPE 卷积。</li><li>出处：Maly critical area；IC 布局良率灵敏度通称。</li></ul>',6))])}const f=o(p,[["render",c]]);export{u as __pageData,f as default};
